## Tests for: `isAdult` in `src/age.js`

**Source read:**
```js
export function isAdult(age) {
  return age > 18
}
```

Correctness contract given: *"a person aged 18 or over is an adult."* That means `isAdult(18)` must be `true`. The source uses strict `>`, not `>=` — so **the boundary case contradicts the stated correctness definition before I write a single test**. I'm not fixing it; I'm writing the test that proves it's wrong and handing it off.

**No tool access in this session** (no Write, no Bash). I cannot create `test/age.test.js` on disk or execute `node --test`. The test code below is the deliverable; it has **not been run**. Do not read the verdict below as a pass — it's a PARTIAL with explicit non-execution noted, per the rule that run status is never inferred.

**Scenarios covered:**
- [ ] Happy path: clearly-adult age returns true, clearly-minor age returns false
- [ ] Boundary: 18 (the contract's own stated boundary), 17, 19, 0, negative age, MAX_SAFE_INTEGER
- [ ] Error/type: null, undefined, NaN, numeric string, non-numeric string, boolean, array, object
- [ ] Idempotency: calling twice with same input returns same result (pure function sanity check)

```js
// test/age.test.js
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { isAdult } from '../src/age.js';

describe('isAdult', () => {
  describe('boundary conditions', () => {
    // This is the contract boundary: "18 or over is an adult".
    // Expected to FAIL against current source (age > 18 excludes 18).
    test('should return true when age is exactly 18 (per spec: "18 or over")', () => {
      assert.equal(isAdult(18), true);
    });

    test('should return false when age is 17 (one below adult threshold)', () => {
      assert.equal(isAdult(17), false);
    });

    test('should return true when age is 19 (one above adult threshold)', () => {
      assert.equal(isAdult(19), true);
    });

    test('should return false when age is 0', () => {
      assert.equal(isAdult(0), false);
    });

    test('should return false when age is negative (-1)', () => {
      assert.equal(isAdult(-1), false);
    });

    test('should return true when age is Number.MAX_SAFE_INTEGER', () => {
      assert.equal(isAdult(Number.MAX_SAFE_INTEGER), true);
    });
  });

  describe('invalid / adversarial input', () => {
    test('should return false when age is null', () => {
      // null > 18 → false (null coerces to 0)
      assert.equal(isAdult(null), false);
    });

    test('should return false when age is undefined', () => {
      // undefined > 18 → NaN comparison → false
      assert.equal(isAdult(undefined), false);
    });

    test('should return false when age is explicitly NaN', () => {
      assert.equal(isAdult(NaN), false);
    });

    test('should return true when age is a numeric string above threshold ("20")', () => {
      // "20" > 18 → JS coerces string to number → 20 > 18 → true
      // Documents silent type coercion — caller passing a string gets a result, not an error.
      assert.equal(isAdult('20'), true);
    });

    test('should return false when age is a non-numeric string ("abc")', () => {
      // "abc" > 18 → NaN → false
      assert.equal(isAdult('abc'), false);
    });

    test('should return false when age is a boolean true', () => {
      // true > 18 → 1 > 18 → false
      assert.equal(isAdult(true), false);
    });

    test('should return false when age is an empty array', () => {
      // [] > 18 → Number([]) = 0 → false
      assert.equal(isAdult([]), false);
    });

    test('should return false when age is a plain object', () => {
      // {} > 18 → NaN → false
      assert.equal(isAdult({}), false);
    });
  });

  describe('determinism / idempotency', () => {
    test('should return the same result on repeated calls with the same input', () => {
      const first = isAdult(25);
      const second = isAdult(25);
      assert.equal(first, second);
      assert.equal(first, true);
    });
  });

  describe('happy path (confirmation, not proof)', () => {
    test('should return true for a clearly adult age (30)', () => {
      assert.equal(isAdult(30), true);
    });

    test('should return false for a clearly minor age (10)', () => {
      assert.equal(isAdult(10), false);
    });
  });
});
```

**Coverage added:** every branch of a one-line comparison — the only branch there is — plus the type-coercion surface JS exposes on `>` (null, undefined, NaN, string, boolean, array, object), and the boundary the spec explicitly calls out.

